export type DateRangeFilter = {
  type: "dateRange";
  columnId: string;
  from?: Date;
  to?: Date;
};

export type MultiSelectFilter = {
  type: "multiSelect";
  columnId: string;
  values: string[];
};

export type ActiveFilter = DateRangeFilter | MultiSelectFilter;

import { X } from "lucide-react";
import { Badge } from "../ui/badge";
import type { ActiveFilter } from "./type";
import { Button } from "../ui/button";
import { format } from "date-fns";

export function ActiveFilterChips({
  filters,
  onRemove,
  onClearAll,
}: {
  filters: ActiveFilter[];
  onRemove: (columnId: string) => void;
  onClearAll: () => void;
}) {
  if (filters.length === 0) return null;

  return (
    <div className="flex items-center gap-2 flex-wrap">
      {filters.map((f) => (
        <Badge key={f.columnId} variant="secondary" className="gap-1 pr-1">
          {formatFilterLabel(f)}
          <button onClick={() => onRemove(f.columnId)}>
            <X className="h-3 w-3" />
          </button>
        </Badge>
      ))}
      <Button variant="ghost" size="sm" onClick={onClearAll}>
        Clear all
      </Button>
    </div>
  );
}

function formatFilterLabel(f: ActiveFilter) {
  if (f.type === "dateRange") {
    return `${f.columnId}: ${f.from ? format(f.from, "MMM d") : "?"} - ${f.to ? format(f.to, "MMM d") : "?"}`;
  }
  return `${f.columnId}: ${f.values.join(", ")}`;
}

'use client'

import { format } from 'date-fns'

import type { ColumnDef, FilterFn } from '@tanstack/react-table'

export type Task = {
  id: string
  title: string
  category: string
  priority: string
  status: string
  dueDate: Date
}

const multiSelectFilter: FilterFn<Task> = (row, columnId, filterValue: string[]) => {
  if (!filterValue?.length) return true
  return filterValue.includes(row.getValue(columnId))
}

const dateRangeFilter: FilterFn<Task> = (
  row,
  columnId,
  filterValue: { from?: Date; to?: Date },
) => {
  const value = row.getValue<Date>(columnId)
  if (filterValue?.from && value < filterValue.from) return false
  if (filterValue?.to && value > filterValue.to) return false
  return true
}

export const columns: ColumnDef<Task>[] = [
  {
    accessorKey: 'title',
    header: 'Title',
  },
  {
    accessorKey: 'category',
    header: 'Category',
    filterFn: multiSelectFilter,
  },
  {
    accessorKey: 'priority',
    header: 'Priority',
  },
  {
    accessorKey: 'status',
    header: 'Status',
  },
  {
    accessorKey: 'dueDate',
    header: 'Due date',
    filterFn: dateRangeFilter,
    cell: ({ getValue }) => format(getValue<Date>(), 'MMM d, yyyy'),
  },
]

'use client'

import { useMemo, useState } from 'react'
import { format } from 'date-fns'
import { CalendarIcon } from 'lucide-react'
import {
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  useReactTable,
} from '@tanstack/react-table'

import type { ColumnDef, ColumnFiltersState } from '@tanstack/react-table'
import type { DateRange } from 'react-day-picker'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { Input } from '#/components/ui/input'
import { Button } from '#/components/ui/button'
import { Calendar } from '#/components/ui/calendar'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '#/components/ui/popover'
import { MultiSelectFilter } from '#/components/ui/multiple-select-filter'
import { ActiveFilterChips } from './active-filter-chips'
import type { ActiveFilter } from './type'

interface FilterOption {
  value: string
  label: string
}

interface FilterStateShapeDataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  categoryOptions: FilterOption[]
}

export function FilterStateShapeDataTable<TData, TValue>({
  columns,
  data,
  categoryOptions,
}: FilterStateShapeDataTableProps<TData, TValue>) {
  const [globalFilter, setGlobalFilter] = useState('')
  const [filters, setFilters] = useState<ActiveFilter[]>([])

  const categoryFilter = filters.find(
    (f): f is Extract<ActiveFilter, { type: 'multiSelect' }> =>
      f.type === 'multiSelect' && f.columnId === 'category',
  )
  const dueDateFilter = filters.find(
    (f): f is Extract<ActiveFilter, { type: 'dateRange' }> =>
      f.type === 'dateRange' && f.columnId === 'dueDate',
  )

  function setCategoryValues(values: string[]) {
    setFilters((prev) => {
      const rest = prev.filter((f) => f.columnId !== 'category')
      if (values.length === 0) return rest
      return [...rest, { type: 'multiSelect', columnId: 'category', values }]
    })
  }

  function setDueDateRange(range: DateRange | undefined) {
    setFilters((prev) => {
      const rest = prev.filter((f) => f.columnId !== 'dueDate')
      if (!range?.from && !range?.to) return rest
      return [
        ...rest,
        {
          type: 'dateRange',
          columnId: 'dueDate',
          from: range?.from,
          to: range?.to,
        },
      ]
    })
  }

  function removeFilter(columnId: string) {
    setFilters((prev) => prev.filter((f) => f.columnId !== columnId))
  }

  function clearAll() {
    setFilters([])
  }

  // `filters` is the single source of truth for structured filters — it
  // drives both the toolbar controls and the chips row. columnFilters is
  // derived from it rather than owned by the table.
  const columnFilters = useMemo<ColumnFiltersState>(
    () =>
      filters.map((f) =>
        f.type === 'multiSelect'
          ? { id: f.columnId, value: f.values }
          : { id: f.columnId, value: { from: f.from, to: f.to } },
      ),
    [filters],
  )

  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onGlobalFilterChange: setGlobalFilter,
    state: {
      columnFilters,
      globalFilter,
    },
  })

  return (
    <div>
      <div className="mb-3 flex flex-wrap items-center gap-2">
        <Input
          placeholder="Search tasks..."
          value={globalFilter}
          onChange={(e) => table.setGlobalFilter(e.target.value)}
          className="w-full sm:w-64"
        />
        <MultiSelectFilter
          title="Category"
          options={categoryOptions}
          selected={categoryFilter?.values ?? []}
          onChange={setCategoryValues}
        />
        <Popover>
          <PopoverTrigger asChild>
            <Button variant="outline" size="sm">
              <CalendarIcon className="mr-2 h-4 w-4" />
              {dueDateFilter?.from ? (
                dueDateFilter.to ? (
                  <>
                    {format(dueDateFilter.from, 'MMM d')} –{' '}
                    {format(dueDateFilter.to, 'MMM d')}
                  </>
                ) : (
                  format(dueDateFilter.from, 'MMM d')
                )
              ) : (
                'Due date'
              )}
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-auto p-0" align="start">
            <Calendar
              mode="range"
              defaultMonth={dueDateFilter?.from}
              selected={
                dueDateFilter
                  ? { from: dueDateFilter.from, to: dueDateFilter.to }
                  : undefined
              }
              onSelect={setDueDateRange}
              numberOfMonths={2}
            />
          </PopoverContent>
        </Popover>
      </div>

      <div className="mb-3">
        <ActiveFilterChips
          filters={filters}
          onRemove={removeFilter}
          onClearAll={clearAll}
        />
      </div>

      <div className="overflow-hidden rounded-md border">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((headerGroup) => (
              <TableRow key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <TableHead key={header.id}>
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </TableHead>
                ))}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length ? (
              table.getRowModel().rows.map((row) => (
                <TableRow key={row.id}>
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            ) : (
              <TableRow>
                <TableCell
                  colSpan={columns.length}
                  className="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            )}
          </TableBody>
        </Table>
      </div>
    </div>
  )
}

import { PlusCircle } from "lucide-react";
import { Button } from "./button";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";
import { Badge } from "./badge";
import { Command, CommandGroup, CommandInput, CommandItem, CommandList } from "./command";
import { Checkbox } from "./checkbox";

export function MultiSelectFilter({
  title,
  options,
  selected,
  onChange,
}: {
  title: string;
  options: { label: string; value: string; count?: number }[];
  selected: string[];
  onChange: (values: string[]) => void;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button variant="outline" size="sm">
          <PlusCircle className="mr-2 h-4 w-4" />
          {title}
          {selected.length > 0 && (
            <Badge variant="secondary" className="ml-2">
              {selected.length}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent className="w-[200px] p-0" align="start">
        <Command>
          <CommandInput placeholder={title} />
          <CommandList>
            <CommandGroup>
              {options.map((option) => {
                const isSelected = selected.includes(option.value);
                return (
                  <CommandItem
                    key={option.value}
                    onSelect={() => {
                      onChange(
                        isSelected
                          ? selected.filter((v) => v !== option.value)
                          : [...selected, option.value]
                      );
                    }}
                  >
                    <Checkbox checked={isSelected} className="mr-2" />
                    <span>{option.label}</span>
                    {option.count !== undefined && (
                      <span className="ml-auto text-muted-foreground text-xs">
                        {option.count}
                      </span>
                    )}
                  </CommandItem>
                );
              })}
            </CommandGroup>
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}
